(function(){
 const nav=document.querySelector('.dashboard nav'),form=document.querySelector('#editor-form');
 const tab=document.createElement('button');tab.type='button';tab.className='tab';tab.dataset.tab='hero';tab.textContent='Первый экран';nav.prepend(tab);
 const panel=document.createElement('section');panel.className='panel';panel.dataset.panel='hero';panel.innerHTML='<div class="panel-head"><h2>Первый экран</h2><p>Заголовок, описание и кнопка поверх фото или видео. Проверьте кадрирование в двух форматах перед сохранением.</p></div><div id="hero-text-fields" class="form-grid"></div><div id="hero-settings" class="form-grid"></div><div id="hero-media-fields" class="media-grid"></div><div class="hero-preview-toolbar"><h3>Предпросмотр</h3><button type="button" data-hero-view="desktop" aria-pressed="true">Компьютер</button><button type="button" data-hero-view="mobile" aria-pressed="false">Телефон</button></div><div class="hero-preview-wrap"><section class="hero-editor-preview"><img class="home-photo" alt=""><video class="home-film" muted loop autoplay playsinline aria-hidden="true"></video><div class="film-shade"></div><div class="home-title"><h1></h1><p></p><a class="button" href="#" tabindex="-1">Выбрать путешествие</a></div><p class="film-caption"></p></section></div><p id="hero-preview-status" role="status"></p>';
 form.insertBefore(panel,form.firstChild);
 tab.setAttribute('role','tab');tab.setAttribute('aria-selected','false');tab.onclick=()=>{activateAdminTab(tab);refreshPreview()};
 let cleanup=()=>{},small=false,objectUrls=new Map();
 const original=renderEditor;
 renderEditor=function(){cleanup();objectUrls.forEach(URL.revokeObjectURL);objectUrls.clear();original();renderHero()};
 const input=(key,label,value,type='text')=>`<label class="field"><span>${label}</span><input name="content.${key}" type="${type}" value="${escapeAttr(value)}" ${type==='range'?'min="0" max="100" step="1"':''}></label>`;
 const select=(key,label,values,current)=>`<label class="field"><span>${label}</span><select name="content.${key}">${values.map(([v,l])=>`<option value="${v}" ${v===current?'selected':''}>${l}</option>`).join('')}</select></label>`;
 function renderHero(){const s=VisaHero.settings(activeConfig),c=activeConfig.content||{};
  const texts=document.querySelector('#hero-text-fields');texts.replaceChildren();['heroTitle','heroCopy'].forEach(key=>{const field=form.querySelector(`[name="content.${key}"]`)?.closest('label');if(field)texts.appendChild(field)});
  document.querySelector('#hero-settings').innerHTML=select('heroMode','Фон первого экрана',[['video','Видео'],['photo','Фотография']],s.mode)+select('heroHeight','Высота первого экрана',[['full','На высоту экрана'],['compact','Компактный']],s.height)+input('heroButton','Текст кнопки',s.button)+input('heroButtonUrl','Ссылка кнопки',c.heroButtonUrl||'/trips.html')+input('heroCaption','Подпись внизу',s.caption)+`<label class="field"><span>Затемнение: <output id="hero-shade-value">${s.shade}%</output></span><input type="range" min="25" max="90" name="content.heroShade" value="${s.shade}"></label>`+input('heroX','Кадр на компьютере · горизонталь',s.x,'range')+input('heroY','Кадр на компьютере · вертикаль',s.y,'range')+input('heroMobileX','Кадр на телефоне · горизонталь',s.mobileX,'range')+input('heroMobileY','Кадр на телефоне · вертикаль',s.mobileY,'range');
  const mediaRoot=document.querySelector('#hero-media-fields');mediaRoot.replaceChildren();
  for(const key of ['heroPoster','heroVideo']){const card=form.querySelector(`[name="media.${key}"]`)?.closest('.media-editor');if(card){mediaRoot.appendChild(card);card.querySelector('.media-note').textContent=key==='heroVideo'?'MP4 (H.264) или WebM, до 40 МБ. Рекомендуем 1920×1080, 10–20 секунд, без звука.':'Фото или обложка видео · JPG/PNG/WebP, до 5 МБ. Показывается до загрузки видео.';card.querySelector('h3').textContent=key==='heroVideo'?'Видео для компьютера':'Фото / обложка для компьютера'}}
  for(const [key,label,video]of [['heroMobilePoster','Фото / обложка для телефона',false],['heroMobileVideo','Видео для телефона',true]]){const card=document.createElement('article');card.className='media-editor';card.innerHTML=`<h3>${label}</h3><label class="field"><span>URL файла · необязательно</span><input name="media.${key}" value="${escapeAttr(activeConfig.media?.[key]||'')}"></label><label class="field"><span>Загрузить файл</span><input type="file" data-media-upload="${key}" accept="${video?'video/mp4,video/webm':'image/jpeg,image/png,image/webp'}"></label><p class="media-note">${video?'Вертикальное видео 9:16, до 40 МБ.':'Вертикальное фото, до 5 МБ.'} Если не задано — используется материал для компьютера.</p>`;mediaRoot.appendChild(card)}
  mediaRoot.querySelectorAll('[data-media-upload]').forEach(el=>el.onchange=()=>uploadHero(el));
  panel.querySelectorAll('input,textarea,select').forEach(el=>el.addEventListener('input',refreshPreview));
  document.querySelectorAll('[data-hero-view]').forEach(b=>b.onclick=()=>{small=b.dataset.heroView==='mobile';document.querySelectorAll('[data-hero-view]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));refreshPreview()});refreshPreview();
 }
 function currentConfig(){const content={...activeConfig.content},media={...defaultMedia,...activeConfig.media};panel.querySelectorAll('[name^="content."]').forEach(el=>content[el.name.slice(8)]=el.value);panel.querySelectorAll('[name^="media."]').forEach(el=>media[el.name.slice(6)]=el.value);objectUrls.forEach((value,key)=>media[key]=value);return{content,media}}
 function refreshPreview(){cleanup();const preview=panel.querySelector('.hero-editor-preview'),cfg=currentConfig();preview.classList.toggle('preview-mobile',small);preview.querySelector('h1').textContent=String(cfg.content.heroTitle||defaultContent.heroTitle).replace(/<br\s*\/?\s*>/gi,'\n').replace(/<[^>]*>/g,'');preview.querySelector('.home-title p').textContent=cfg.content.heroCopy||defaultContent.heroCopy;const output=panel.querySelector('#hero-shade-value');if(output)output.textContent=(cfg.content.heroShade||65)+'%';cleanup=VisaHero.mount(cfg,preview,{mobile:small,preview:true});preview.querySelector('.home-title a').onclick=e=>e.preventDefault()}
 async function uploadHero(input){const file=input.files?.[0];if(!file)return;const key=input.dataset.mediaUpload,video=key.endsWith('Video'),max=video?40000000:5000000,types=video?['video/mp4','video/webm']:['image/jpeg','image/png','image/webp'];const status=document.querySelector('#hero-preview-status');if(!types.includes(file.type)||file.size>max){status.textContent=`Выберите ${video?'MP4 или WebM до 40 МБ':'JPG, PNG или WebP до 5 МБ'}.`;input.value='';return}if(objectUrls.has(key))URL.revokeObjectURL(objectUrls.get(key));const local=URL.createObjectURL(file);objectUrls.set(key,local);mediaUploads[key]=file;markCatalogDirty();status.textContent='Файл выбран. Нажмите «Сохранить изменения», чтобы загрузить его на сайт.';refreshPreview()}
 // Clear staged files when a URL is explicitly edited instead of an uploaded file.
 panel.addEventListener('input',event=>{const name=event.target.name||'';if(name.startsWith('media.')){const key=name.slice(6);if(objectUrls.has(key)){URL.revokeObjectURL(objectUrls.get(key));objectUrls.delete(key)}delete mediaUploads[key];refreshPreview()}});
 const save=form.onsubmit;form.onsubmit=async event=>{const cfg=currentConfig();for(const key of ['heroPoster','heroVideo','heroMobilePoster','heroMobileVideo'])if(cfg.media[key]&&!String(cfg.media[key]).startsWith('blob:')&&!VisaCatalog.url(cfg.media[key])){event.preventDefault();document.querySelector('#save-status').textContent='Проверьте ссылки на материалы первого экрана.';return}if(!VisaCatalog.url(cfg.content.heroButtonUrl||'/trips.html')){event.preventDefault();document.querySelector('#save-status').textContent='Укажите корректную ссылку кнопки первого экрана.';return}await save(event);if(!catalogDirty){cleanup();objectUrls.forEach(URL.revokeObjectURL);objectUrls.clear();panel.querySelectorAll('[name^="media."]').forEach(el=>el.value=activeConfig.media?.[el.name.slice(6)]||'');refreshPreview()}};
 if(form.querySelector('[name="content.heroTitle"]'))renderHero();
})();
